namespace ghidra.app.plugin.core.totd;






using ghidra.app;
using ghidra.app.plugin;
using ghidra.framework.main;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool.util;
using ghidra.framework.preferences;
using ghidra.util;
using ghidra.util;
using utilities.util;

//@formatter:off
/* @PluginInfo(
	status = PluginStatus.RELEASED,
	packageName = CorePluginPackage.NAME,
	category = PluginCategoryNames.COMMON,
	shortDescription = "Tip Of The Day",
	description = "Display a dialog containing 'Tips of the Day'."
) */
//@formatter:on
public class TipOfTheDayPlugin : Plugin, ApplicationLevelOnlyPlugin {
	private static readonly string TIP_INDEX = "TIP_INDEX";
	private static readonly string SHOW_TIPS = "SHOW_TIPS";

	private TipOfTheDayDialog dialog;

	public TipOfTheDayPlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	protected void init() {
		List<string> tips = null;
		try {
			tips = loadTips();
		}
		catch (IOException e) {
			tips = new();
		}
		dialog = new TipOfTheDayDialog(this, tips);

		readPreferences();
	}

	private List<string> loadTips()
    {
		using (InputStream @in = getClass().getResourceAsStream("tips.txt"))
{
			List<string> tips = in == null ? Collections.emptyList() : FileUtilities.getLines(@in);
			return tips.stream().filter(s => s.length() > 0).collect(Collectors.toList());
		}
	}

	/* @Override */
	protected void dispose() {
		writePreferences();
		dialog.close();
	}

	private void readPreferences() {
		string tipIndexStr = Preferences.getProperty(TIP_INDEX, "0", true);
		string showTipsStr = Preferences.getProperty(SHOW_TIPS, "true", true);

		int tipIndex = Integer.parseInt(tipIndexStr);
		bool showTips = Boolean.parseBoolean(showTipsStr);
		if (showTips) {
			tipIndex = (++tipIndex) % dialog.getNumberOfTips();
			writePreferences(tipIndex, showTips);
		}

		dialog.setTipIndex(tipIndex);
		dialog.setShowTips(showTips);

		Swing.runLater(() => {
			if (showTips && !SystemUtilities.isInTestingMode()) {
				dialog.show(tool.getToolFrame());
			}
			else {
				dialog.close();
			}
		});
	}

	void writePreferences() {
		if (dialog != null) {
			writePreferences(dialog.getTipIndex(), dialog.showTips());
		}
	}

	private void writePreferences(int tipIndex, bool showTips) {
		Preferences.setProperty(TIP_INDEX, "" + tipIndex);
		Preferences.setProperty(SHOW_TIPS, "" + showTips);
		Preferences.store();
	}
}
